\set ON_ERROR_STOP on
begin;
insert into auth.users(id) values('00000000-0000-4000-8000-000000000001');
insert into admins(user_id) values('00000000-0000-4000-8000-000000000001');
do $$
declare actor uuid:='00000000-0000-4000-8000-000000000001'; eq uuid; unit uuid; r1 uuid; r2 uuid; stock uuid; retry uuid:=gen_random_uuid(); gallery uuid; share text; ref text; b1 uuid; b2 uuid; denied boolean;
begin
 perform save_record(actor,'equipment',null,'{"name":"Test camera","category":"Cameras","published":true}');
 select id into eq from equipment where name='Test camera';
 perform save_record(actor,'equipment_units',null,jsonb_build_object('equipment_id',eq,'code','TEST-001','status','active'));
 select id into unit from equipment_units where equipment_id=eq;
 r1:=gen_random_uuid(); r2:=gen_random_uuid();
 ref:=create_rental(jsonb_build_object('id',r1,'name','Test client','phone','0000000000','email','test@example.invalid','address','Test only','starts_at','2030-01-01T10:00:00Z','ends_at','2030-01-03T10:00:00Z','notes',''),jsonb_build_array(jsonb_build_object('equipment_id',eq,'quantity',1)),'[{"kind":"id_front","storage_key":"test-front"},{"kind":"id_back","storage_key":"test-back"},{"kind":"selfie","storage_key":"test-selfie"}]');
 if (select count(*) from reservations where rental_id=r1)<>0 then raise exception 'Pending request reserved units'; end if;
 perform update_rental(actor,r1,'{"status":"Approved"}');
 if (select count(*) from reservations where rental_id=r1 and not released)<>1 then raise exception 'Approval did not assign physical unit'; end if;
 perform create_rental(jsonb_build_object('id',r2,'name','Test client two','phone','0000000000','email','test@example.invalid','address','Test only','starts_at','2030-01-02T10:00:00Z','ends_at','2030-01-04T10:00:00Z','notes',''),jsonb_build_array(jsonb_build_object('equipment_id',eq,'quantity',1)),'[{"kind":"id_front","storage_key":"test-front-2"},{"kind":"id_back","storage_key":"test-back-2"},{"kind":"selfie","storage_key":"test-selfie-2"}]');
 denied:=false; begin perform update_rental(actor,r2,'{"status":"Approved"}'); exception when others then denied:=true; end;
 if not denied or (select status from rentals where id=r2)<>'Pending Review' then raise exception 'Overlapping rental approved'; end if;
 perform update_rental(actor,r1,'{"status":"Cancelled"}'); perform update_rental(actor,r2,'{"status":"Approved"}');
 if exists(select 1 from reservations where rental_id=r1 and not released) then raise exception 'Cancellation did not release units'; end if;
 denied:=false;begin perform save_record(actor,'equipment_units',unit,'{"status":"maintenance"}');exception when others then denied:=true;end;
 if not denied then raise exception 'Reserved unit put in maintenance';end if;
 denied:=false;begin perform update_rental(actor,r2,'{"status":"Returned"}');exception when others then denied:=true;end;
 if not denied then raise exception 'Invalid rental transition accepted';end if;
 raise notice 'PASS: rental allocation, overlap rejection, cancellation release, maintenance and transitions';
 perform update_rental(actor,r2,jsonb_build_object('assigned_unit_ids',jsonb_build_array(unit),'starts_at','2020-01-01T10:00:00Z','ends_at','2020-01-03T10:00:00Z','status','Ready for Pickup'));
 denied:=false;begin perform update_rental(actor,r2,'{"status":"Collected"}');exception when others then denied:=true;end;
 if not denied then raise exception 'Handover recorded without equipment condition';end if;
 perform update_rental(actor,r2,'{"status":"Collected","pickup_condition":"All parts checked, clean"}');
 if not exists(select 1 from rentals where id=r2 and collected_at is not null and handed_over_by=actor and phone_confirmed_at is not null) then raise exception 'Handover time or responsible staff not recorded';end if;
 if (select available from availability('2040-01-01','2040-01-03') where equipment_id=eq)<>0 then raise exception 'Overdue physical unit became available';end if;
 perform update_rental(actor,r2,'{"ends_at":"2021-01-03T10:00:00Z"}');
 if not exists(select 1 from reservations where rental_id=r2 and unit_id=unit and not released) then raise exception 'Collected physical assignment changed';end if;
 perform update_rental(actor,r2,'{"status":"Returned","return_condition":"All equipment returned in good condition"}');
 if not exists(select 1 from rentals where id=r2 and returned_at is not null and returned_by=actor) then raise exception 'Return time or responsible staff not recorded';end if;
 if (select available from availability('2040-01-01','2040-01-03') where equipment_id=eq)<>1 then raise exception 'Returned unit unavailable';end if;
 raise notice 'PASS: explicit unit assignment, overdue blocking, preserved collected units and returns';
 if exists(select 1 from financial_transactions where rental_id in(r1,r2)) then raise exception 'Rental workflow created a financial entry automatically';end if;
 raise notice 'PASS: handover/return conditions, staff timestamps and optional financial records';
 perform save_record(actor,'inventory',null,'{"name":"Test paper","category":"Paper","sku":"TEST-PAPER","reorder_threshold":5,"unit_cost":10}');
 select id into stock from inventory where sku='TEST-PAPER';
 perform move_stock(actor,stock,10,'Restock','Test',retry); perform move_stock(actor,stock,10,'Restock','Test retry',retry);
 if (select quantity from inventory where id=stock)<>10 then raise exception 'Duplicate stock movement';end if;
 denied:=false;begin perform move_stock(actor,stock,-11,'Usage','Test negative',gen_random_uuid());exception when check_violation then denied:=true;end;
 if not denied or (select quantity from inventory where id=stock)<>10 then raise exception 'Negative stock or partial update';end if;
 raise notice 'PASS: stock movements are atomic, idempotent and prevent negative balances';
 retry:=gen_random_uuid();perform record_payment(actor,'{"date":"2030-01-01","kind":"Income","category":"Test","amount":123.45,"description":"Test payment","payment_method":"Cash"}',retry);
 perform record_payment(actor,'{"date":"2030-01-01","kind":"Income","category":"Test","amount":123.45,"description":"Retry payment","payment_method":"Cash"}',retry);
 if (select count(*) from financial_transactions where idempotency_key=retry)<>1 then raise exception 'Payment retry duplicated';end if;
 if (select amount from financial_transactions where idempotency_key=retry)<>123.45 then raise exception 'Money lost precision';end if;
 perform void_payment(actor,(select id from financial_transactions where idempotency_key=retry),'Correction test');
 if not exists(select 1 from audit_events where table_name='financial_transactions' and operation='UPDATE') then raise exception 'Void missing audit trail';end if;
 raise notice 'PASS: exact money, payment deduplication, void and audit history';
 perform record_payment(actor,jsonb_build_object('date','2030-01-01','kind','Deposit','category','Rental deposit','amount',100,'description','Test deposit','payment_method','Cash','rental_id',r2),gen_random_uuid());
 perform record_payment(actor,jsonb_build_object('date','2030-01-01','kind','Refund','category','Deposit refund','amount',25,'description','Test refund','payment_method','Cash','rental_id',r2),gen_random_uuid());
 denied:=false;begin perform record_payment(actor,jsonb_build_object('date','2030-01-01','kind','Refund','category','Deposit refund','amount',100,'description','Too much','payment_method','Cash','rental_id',r2),gen_random_uuid());exception when others then denied:=true;end;
 if not denied then raise exception 'Refund exceeded held deposit';end if;
 raise notice 'PASS: refundable deposit tracking and excessive refund rejection';
 gallery:=save_gallery(actor,null,'{"title":"Test gallery","client_name":"Test client","published":true}','secret',false);
 select token into share from event_galleries where id=gallery;
 if length(share)<>64 or unlock_gallery(share,'wrong') is not null or unlock_gallery(share,'secret') is null then raise exception 'Passcode gate failed';end if;
 if unlock_gallery(share,'secret') ? 'passcode_hash' then raise exception 'Passcode hash leaked';end if;
 perform save_gallery(actor,gallery,'{"expires_at":"2000-01-01T00:00:00Z"}','',false);
 if unlock_gallery(share,'secret') is not null then raise exception 'Expired gallery accessible';end if;
 perform save_gallery(actor,gallery,'{"expires_at":null,"revoked":true}','',false);
 if unlock_gallery(share,'secret') is not null then raise exception 'Revoked gallery accessible';end if;
 perform save_gallery(actor,gallery,'{"revoked":false}','',true);
 if unlock_gallery(share,'secret') is not null then raise exception 'Old share token still valid';end if;
 raise notice 'PASS: gallery passcodes, expiry, revocation, token rotation and safe DTO';
 if consume_rate('test-key',2,60) is not true or consume_rate('test-key',2,60) is not true or consume_rate('test-key',2,60) is not false then raise exception 'Rate limit failed';end if;
 perform set_settings(actor,'{"phone":"TEST-PHONE"}');
 if (select value->>'phone' from settings where id='studio')<>'TEST-PHONE' then raise exception 'Settings update failed';end if;
 denied:=false;begin perform check_actor(gen_random_uuid());exception when others then denied:=true;end;
 if not denied then raise exception 'Non-admin mutation allowed';end if;
 insert into bookings(name,phone,email,service,starts_at,ends_at) values('Test booking one','0000000000','test@example.invalid','Portrait','2030-01-01 10:00Z','2030-01-01 12:00Z') returning id into b1;
 insert into bookings(name,phone,email,service,starts_at,ends_at) values('Test booking two','0000000000','test@example.invalid','Portrait','2030-01-01 11:00Z','2030-01-01 13:00Z') returning id into b2;
 perform update_booking(actor,b1,'{"status":"Confirmed"}');
 denied:=false;begin perform update_booking(actor,b2,'{"status":"Confirmed"}');exception when others then denied:=true;end;
 if not denied then raise exception 'Booking overlap did not warn';end if;
 perform update_booking(actor,b2,'{"status":"Confirmed"}',true);
 raise notice 'PASS: public rate limits, studio settings, authorization and booking overlap acknowledgment';
 if has_function_privilege('anon','public.update_rental(uuid,uuid,jsonb)','execute') or has_function_privilege('authenticated','public.move_stock(uuid,uuid,numeric,text,text,uuid)','execute') then raise exception 'Public privileged RPC access';end if;
 if exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and qual like '%verification%') then raise exception 'Private documents have public policy';end if;
 raise notice 'PASS: privileged RPC grants and private storage policy';
end $$;
grant select on all tables in schema public to anon,authenticated;
set local role anon;
do $$begin
 if exists(select 1 from bookings) or exists(select 1 from rentals) or exists(select 1 from verification_documents) or exists(select 1 from event_galleries) or exists(select 1 from financial_transactions) or exists(select 1 from inventory) then raise exception 'RLS exposed private data';end if;
 if not exists(select 1 from settings) then raise exception 'Public settings missing';end if;
 raise notice 'PASS: anonymous role cannot read client, document, gallery, financial or inventory data';
end$$;
reset role;
rollback;
